Tool response:
Tool: create_purchase_order
Description: Create Purchase Order
Parameters:
    {
      "type": "object",
      "properties": {
        "supplier_id": {
          "type": "integer",
          "title": "Supplier Id"
        },
        "warehouse_id": {
          "type": "integer",
          "title": "Warehouse Id"
        },
        "requested_delivery_date": {
          "type": "string",
          "title": "Requested Delivery Date"
        },
        "lines": {
          "items": {
            "properties": {
              "part_number": {
                "type": "string",
                "title": "Part Number"
              },
              "quantity": {
                "type": "integer",
                "title": "Quantity"
              }
            },
            "type": "object",
            "required": [
              "part_number",
              "quantity"
            ],
            "title": "PurchaseOrderLineInput"
          },
          "type": "array",
          "title": "Lines"
        }
      },
      "required": [
        "supplier_id",
        "warehouse_id",
        "requested_delivery_date",
        "lines"
      ]
    }
